        for(int i=pendingPhases.size()-1;i>=0;i--){JsonObject p=pendingPhases.get(i);if(pc==p.get("return_address_value").getAsLong()&&h.sp()==p.get("entry_sp_value").getAsLong()+4){p.addProperty("d0_return_word",(short)h.cpu.readRegister("D0").intValue());p.add("after",smallSnap(h,r));pendingPhases.remove(i);}}
