        for(long point:new long[]{0x15014c,0x150156,0x150588,0x1505d2,0x150686,0x150694,0x15069e,0x150742,0x15108c,0x1511fc,0x151920,0x15193a,0x151954,0x15195a,0x151974,0x15197a,0x151a2c})if(pc==point){JsonObject e=new JsonObject();e.addProperty("address",Long.toHexString(pc));e.addProperty("d0_word",(short)h.cpu.readRegister("D0").intValue());e.addProperty("d3_word",(short)h.cpu.readRegister("D3").intValue());e.addProperty("d4_word",(short)h.cpu.readRegister("D4").intValue());e.addProperty("d5_byte",(byte)h.cpu.readRegister("D5").intValue());e.add("before_instruction",smallSnap(h,r));conditionEvents.add(e);pendingCondition=e;}
